 TermuxActivity a;AgentProjectPanel panel;List<JSONObject> rows=new ArrayList<>();boolean alive=true,older=true,pending;String error="";Runnable observer=()->{};AtomicInteger refreshes=new AtomicInteger(),pages=new AtomicInteger(),gitReads=new AtomicInteger();volatile boolean failGit,holdGit;CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);
 JSONObject user(String key,String name)throws Exception{return new JSONObject().put("key",key).put("message",key).put("kind","attachment").put("messageSender","user").put("attachment",new JSONObject().put("id","0123456789abcdef0123456789abcdef").put("name",name).put("path","/synthetic/"+name).put("bytes",42));}
 AgentProjectPanel.Chat chat=new AgentProjectPanel.Chat(){public boolean valid(){return alive;}public List<JSONObject> rows(){return rows;}public boolean hasOlder(){return older;}public boolean loadingOlder(){return pending;}public String historyError(){return error;}public void refresh(){refreshes.incrementAndGet();pending=true;observer.run();}public void older(){pages.incrementAndGet();try{rows.add(user("older","Beta upload.zip"));}catch(Exception e){throw new AssertionError(e);}older=false;observer.run();}public void retryRead(){refresh();}public void open(JSONObject file){}public boolean jump(String key){return true;}public void observe(Runnable r){observer=r;}public void close(){alive=false;}};
 AgentProjectPanel.Backend backend=new AgentProjectPanel.Backend(){public byte[] read(String script,int max)throws Exception{if(script.contains("rev-parse")){gitReads.incrementAndGet();if(holdGit){entered.countDown();release.await(2,TimeUnit.SECONDS);}if(failGit)throw new java.io.IOException("synthetic failure");return ("OK\0/synthetic\0"+String.join("",Collections.nCopies(40,"a"))+"\0 M src/Main.java\0?? images/photo.bin\0").getBytes();}if(script.contains("MTIME"))return ("MTIME\0"+1700000000L+"\n\0DIFF\0"+(script.contains("photo.bin")?"-\t-\timages/photo.bin\0":"1\t2\tsrc/Main.java\0")).getBytes();if(script.contains("--numstat"))return "TEXT\n-before\n+after\n".getBytes();return "AVAILABLE 42".getBytes();}public void close(){release.countDown();}};
 View text(View v,String exact){if(v instanceof TextView&&((TextView)v).getText().toString().equals(exact))return v;if(v instanceof ViewGroup)for(int n=0;n<((ViewGroup)v).getChildCount();n++){View r=text(((ViewGroup)v).getChildAt(n),exact);if(r!=null)return r;}return null;}
 void idle()throws Exception{for(int n=0;n<20;n++){Shadows.shadowOf(Looper.getMainLooper()).idle();Thread.sleep(5);}}
 String tr(String ru,String en){return WorkspaceLanguage.code(a).equals("ru")?ru:en;}
